from pathlib import Path
p=Path('outputs/index.html');s=p.read_text(encoding='utf-8')
s=s.replace("escapeDistance=1,escapeSelecting=false,myAction=null", "escapeDistance=1,escapeSelecting=false,uiCombatKey='',myAction=null",1)
old="if(state.phase==='combat'&&uiPhase!=='combat'){document.querySelectorAll('[data-action]').forEach(b=>{b.disabled=false;b.classList.remove('sel');b.setAttribute('aria-pressed','false')})}uiPhase=state.phase;"
new="if(state.phase==='combat'){let key=state.round+':'+(state.combatTurn||1);if(key!==uiCombatKey){uiCombatKey=key;escapeSelecting=false;escapeDistance=1;escapeDir=awayDirection(state.players.find(p=>p.id===me?.id)||{x:0,y:0});$('#combatActions').classList.remove('hidden');$('#escapeControls').classList.add('hidden');$('#confirmEscape').disabled=false;document.querySelectorAll('[data-action]').forEach(b=>{b.disabled=false;b.classList.remove('sel');b.setAttribute('aria-pressed','false')});document.querySelectorAll('[data-escape-distance]').forEach(b=>{let yes=b.dataset.escapeDistance==='1';b.classList.toggle('sel',yes);b.setAttribute('aria-pressed',String(yes))});document.querySelectorAll('[data-escape-dir]').forEach(b=>{let [x,y]=b.dataset.escapeDir.split(',').map(Number),yes=x===escapeDir.x&&y===escapeDir.y;b.classList.toggle('sel',yes);b.setAttribute('aria-pressed',String(yes))})}}else uiCombatKey='';uiPhase=state.phase;"
if old not in s: print('combat reset fragment not found')
else:s=s.replace(old,new,1)
old_handler="document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{myAction=b.dataset.action;document.querySelectorAll('[data-action]').forEach(x=>{let yes=x===b;x.classList.toggle('sel',yes);x.setAttribute('aria-pressed',String(yes))});sendHost({type:'action',action:myAction});document.querySelectorAll('[data-action]').forEach(x=>x.disabled=true)});"
new_handler="""document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{myAction=b.dataset.action;document.querySelectorAll('[data-action]').forEach(x=>{let yes=x===b;x.classList.toggle('sel',yes);x.setAttribute('aria-pressed',String(yes))});if(myAction==='escape'){escapeSelecting=true;escapeDistance=1;escapeDir=awayDirection(state.players.find(p=>p.id===me?.id));$('#combatActions').classList.add('hidden');$('#escapeControls').classList.remove('hidden');document.querySelectorAll('[data-escape-distance]').forEach(x=>{let yes=x.dataset.escapeDistance==='1';x.classList.toggle('sel',yes);x.setAttribute('aria-pressed',String(yes))});document.querySelectorAll('[data-escape-dir]').forEach(x=>{let [dx,dy]=x.dataset.escapeDir.split(',').map(Number),yes=dx===escapeDir.x&&dy===escapeDir.y;x.classList.toggle('sel',yes);x.setAttribute('aria-pressed',String(yes))});draw();return}sendHost({type:'action',action:{type:myAction}});document.querySelectorAll('[data-action]').forEach(x=>x.disabled=true)});document.querySelectorAll('[data-escape-distance]').forEach(b=>b.onclick=()=>{escapeDistance=Number(b.dataset.escapeDistance);document.querySelectorAll('[data-escape-distance]').forEach(x=>{let yes=x===b;x.classList.toggle('sel',yes);x.setAttribute('aria-pressed',String(yes))});draw()});document.querySelectorAll('[data-escape-dir]').forEach(b=>b.onclick=()=>{let [x,y]=b.dataset.escapeDir.split(',').map(Number);escapeDir={x,y};document.querySelectorAll('[data-escape-dir]').forEach(q=>{let yes=q===b;q.classList.toggle('sel',yes);q.setAttribute('aria-pressed',String(yes))});draw()});$('#cancelEscape').onclick=()=>{escapeSelecting=false;$('#escapeControls').classList.add('hidden');$('#combatActions').classList.remove('hidden');document.querySelectorAll('[data-action]').forEach(x=>{x.classList.remove('sel');x.setAttribute('aria-pressed','false')});draw()};$('#confirmEscape').onclick=()=>{if(!escapeSelecting)return;sendHost({type:'action',action:{type:'escape',dir:escapeDir,distance:escapeDistance}});$('#confirmEscape').disabled=true;document.querySelectorAll('[data-action]').forEach(x=>x.disabled=true)});"""
if old_handler not in s: print('action handler not found')
else:s=s.replace(old_handler,new_handler,1)
# Reinitialize escape UI with a new protocol.
s=s.replace("moveDir={x:0,y:-1};uiRound=0;", "moveDir={x:0,y:-1};escapeDir={x:0,y:-1};escapeDistance=1;escapeSelecting=false;uiCombatKey='';uiRound=0;",1)
# Remove previous movement-control display when unrelated phases reset.
s=s.replace("function beginMove(){if(!host)return;state.phase='move';", "function beginMove(){if(!host)return;state.phase='move';state.combatTurn=0;",1)
